// Package prometheus generates monitoring targets in the file_sd format
// (docs/adr/ADR-009, decision 2): one JSON file per scrape job.
//
//   - node.json — servers of the model, node_exporter on port 9100;
//   - snmp.json — devices of the model by mgmt_ip, for a job that scrapes
//     them through snmp_exporter.
//
// Each host is its own target group, so its labels — site, name, role,
// platform — travel with it. JSON has no comments, so these files carry no
// "generated by" header; encoding/json sorts the label keys, which keeps the
// output byte for byte stable.
package prometheus

import (
	"encoding/json"
	"strings"

	"orgc/internal/backend"
	"orgc/internal/ir"
)

// NodePort is where node_exporter listens on a server.
const NodePort = "9100"

// Generator renders the targets.
type Generator struct{}

var _ backend.Generator = Generator{}

// Name identifies the generator.
func (Generator) Name() string { return "prometheus" }

type group struct {
	Targets []string          `json:"targets"`
	Labels  map[string]string `json:"labels"`
}

// Generate renders a file per job that has targets, hosts in model order.
func (Generator) Generate(m *ir.Model, _ backend.Platforms) []backend.File {
	var node, snmp []group
	for _, s := range m.Servers {
		roles := make([]string, len(s.Roles))
		for i, r := range s.Roles {
			roles[i] = string(r)
		}
		node = append(node, group{
			Targets: []string{s.IP.String() + ":" + NodePort},
			Labels:  map[string]string{"site": s.Site.Name, "host": s.Name, "roles": strings.Join(roles, ",")},
		})
	}
	for _, d := range m.Devices {
		snmp = append(snmp, group{
			Targets: []string{d.MgmtIP.String()},
			Labels: map[string]string{
				"site": d.Site.Name, "device": d.Name,
				"role": string(d.Role), "platform": string(d.Type),
			},
		})
	}

	var files []backend.File
	for _, job := range []struct {
		name   string
		groups []group
	}{{"node", node}, {"snmp", snmp}} {
		if len(job.groups) == 0 {
			continue
		}
		data, err := json.MarshalIndent(job.groups, "", "  ")
		if err != nil {
			panic(err) // strings only: cannot fail
		}
		files = append(files, backend.File{Path: "prometheus/targets/" + job.name + ".json", Data: append(data, '\n')})
	}
	return files
}
